window.RP_SESSION={"id":"S-f2dbe3b9ff63","messages":[{"id":"RP-II-0103938","time":"2026-05-29T22:04:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"풀.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103939","time":"2026-05-29T22:13:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"부추가 많이 자랐습니다. 초여름이 지나고 한여름이 오면 이것도 다 흐무러져 맛이 없어집니다. 나중에 다시 자랄 자리는 두고 좀 뜯어서 바구니에 담습니다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103940","time":"2026-05-29T22:15:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"민들레도 먹을 수 있는건 유명하죠. 배를 채울 수 있게 하기 위해 적당한 양의 어린 잎을 따서 같이 담습니다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103941","time":"2026-05-29T22:15:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"쇠비름이 자라던 것도 눈에 담아 두었습니다. 적절히 손으로 분질러서 바구니에 담습니다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103942","time":"2026-05-29T22:16:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"큰질경이도 어린잎을 따서 가져가면 이런저런 요리에 쓸 수 있습니다. 꽃이 징그럽게 생겨서 잡초라고 오해를 많이 받지만, 쓸모가 많습니다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103943","time":"2026-05-29T22:19:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"쇠별꽃은 봄에 주로 먹는 식물이지만, 어리고 여린 순을 골라내서 따면 지금도 먹을 수 있는 부위가 있군요.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103944","time":"2026-05-29T22:22:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"와, 명아주가 잔뜩. 이건 노다지네요. 이 시즌에 가장 맛있는... 뭐, 그래봐야 풀이지만요. 호들갑 좀 떨어 보죠.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103945","time":"2026-05-29T22:24:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"그라운드 엘더. 이것도 마귀할멈의 가르침에 의하면 먹을 수 있는 종류의 풀입니다. 꽃이 피기 전까지요. 다행히 아직 꽃이 안 피었군요. 어린 잎들을 골라서 땁니다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103946","time":"2026-05-29T22:25:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"음, 쐐기풀도 일단 삶아서 가시를 제거하면 먹을 수 있긴 한데...","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103947","time":"2026-05-29T22:25:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!지능","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103948","time":"2026-05-29T22:25:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 지능 판정 :\n[8] + [1] = [9]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-II-0103949","time":"2026-05-29T22:27:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"마귀할멈이 가르친대로 염동력을 써서 손을 대지 않고 쐐기풀의 어린 잎들을 따는데 성공합니다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103950","time":"2026-05-29T22:27:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"숲에서 길드 건물로, 두둑해진 바구니를 들고 돌아옵니다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103951","time":"2026-05-29T22:28:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"작은 팟에 쐐기풀 어린 잎을 먼저 삶아서 가시와 독성을 제거합니다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103952","time":"2026-05-29T22:30:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"민들레와 큰질경이는 물로 꼼꼼하게 잘 씻고, 민들레는 쓴맛을 줄이기 위해 소금을 조금 넣은 물에 담가 둡니다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103953","time":"2026-05-29T22:31:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"다른 재료들도 재료가 상하지 않게 물에 살살 흔들어 씻습니다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103954","time":"2026-05-29T22:33:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"주방에 있던 완두콩과 오트밀을 꺼내 옵니다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103955","time":"2026-05-29T22:34:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"솥에 소금과 절인 비계를 넣고 명아주, 큰질경이, 민들레를 넣어 끓이기 시작합니다. 물이 끓으면 완두콩을 먼저 넣습니다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103956","time":"2026-05-29T22:35:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"그것들이 어느 정도 익으면 쇠비름과 데쳐서 독성을 제거해 둔 쐐기풀을 넣습니다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103957","time":"2026-05-29T22:36:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"마지막으로 부추, 그라운드 엘더, 쇠별꽃과 오트밀을 넣어서 야생 식용 풀 스튜를 끓여냅니다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103958","time":"2026-05-29T22:36:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"그리 막 맛있는 음식이 되지는 않겠지만, 매일매일 맛있는 것만 먹고 살 수는 없죠.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103959","time":"2026-05-29T22:40:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"그래도 따끈하고 탄수화물과 단백질, 약간의 지방이 들어간 음식을 입 안에 넣고 꼭꼭 씹어 삼킵니다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103960","time":"2026-05-29T22:40:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"그닥 하루의 위로가 되는 맛은 아니지만, 배고팠다구요.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103961","time":"2026-05-29T22:52:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"1인분은 아닌 것 같은데, 같이 드실 분?","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103962","time":"2026-05-29T23:25:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"없군요...","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103963","time":"2026-05-29T23:25:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103964","time":"2026-05-29T23:25:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"-fin","characters":[]}]};
